# Intermediate unit 4 – Nouns and adjectives based on phrasal verbs. Bám sách: trang 12–13 (đã xem ảnh trang) + đáp án + Mini dictionary (mục ghi unit 4).
# Các từ Mini dictionary xếp vào unit khác (bygone 23, getaway 62, crackdown 66, lie-in 58, lookout 9…) để unit đó. Không chép nguyên văn.
theory = (
 H("A", "Nouns made from verb + particle", "Danh từ tạo từ động từ + tiểu từ")
 + P("Just as <i>invite</i> gives <i>invitation</i>, some phrasal verbs give nouns. Three short dialogues:", "Giống như <i>invite</i> cho ra <i>invitation</i>, một số phrasal verb cho ra danh từ. Ba đoạn hội thoại ngắn:")
 + T([
    ("<b>rip off</b> → <b>rip-off</b>", "Tom paid far too much for a call to an 0877 number; Lily agrees such numbers are a big rip-off.", "Tom bị chặt chém khi gọi số 0877; Lily đồng ý mấy số đó đúng là cắt cổ."),
    ("<b>drop out</b> → <b>dropout</b>", "Grace’s son gave up his college course; Ed says there were many dropouts that year.", "Con trai Grace bỏ học đại học; Ed nói năm đó nhiều người bỏ học."),
    ("<b>break in</b> → <b>break-in</b>", "Someone entered the school by force and stole a computer; Isla says it’s the second one this year.", "Có kẻ đột nhập trường lấy trộm máy tính; Isla nói đây là vụ thứ hai trong năm."),
 ], head=("Verb → noun", "In the dialogue", "Trong hội thoại"))
 + P("Rules: the plural adds <i>-s</i> to the particle (<i>break-ins, dropouts, rip-offs</i>), except <b>goings-on</b>, which is always plural. Nouns ending in <i>-out</i> and <i>-over</i> are usually one word (<i>checkout, handout, changeover, leftovers</i>); those with <i>-in, -up</i> and rarer particles usually take a hyphen (<i>mix-up, put-down, run-through</i>). The stress falls on the verb: a BREAK-in, college DROPouts.", "Quy tắc: số nhiều thêm <i>-s</i> vào tiểu từ (<i>break-ins, dropouts, rip-offs</i>), trừ <b>goings-on</b> luôn ở số nhiều. Danh từ tận cùng <i>-out</i>, <i>-over</i> thường viết liền (<i>checkout, handout, changeover, leftovers</i>); có <i>-in, -up</i> và tiểu từ hiếm hơn thường có gạch nối (<i>mix-up, put-down, run-through</i>). Trọng âm rơi vào động từ: a BREAK-in, college DROPouts.")
 + H("B", "Nouns made from particle + verb", "Danh từ tạo từ tiểu từ + động từ")
 + P("Here the particle comes first and usually carries the stress: <b>set out</b> → <b>outset</b> (the beginning), <b>fall down</b> → <b>downfall</b> (sudden failure, e.g. of a government in an economic crisis), <b>look on</b> → <b>onlooker</b> (someone who watches but doesn’t take part, e.g. crowds watching an arrest).", "Ở đây tiểu từ đứng trước và thường mang trọng âm: <b>set out</b> → <b>outset</b> (lúc đầu), <b>fall down</b> → <b>downfall</b> (sụp đổ, ví dụ chính phủ trong khủng hoảng kinh tế), <b>look on</b> → <b>onlooker</b> (người đứng xem không tham gia, ví dụ đám đông xem cảnh sát bắt người).")
 + H("C", "Adjectives", "Tính từ")
 + P("Some adjectives come from phrasal verbs too: a <b>broken-down</b> vehicle (its engine stopped working), a <b>breakdown</b> vehicle (it helps drivers whose cars have broken down), <b>blocked-up</b> drains (water can’t flow).", "Một số tính từ cũng tạo từ phrasal verb: xe <b>broken-down</b> (chết máy), xe <b>breakdown</b> (xe cứu hộ), cống <b>blocked-up</b> (tắc, nước không chảy được).")
 + NOTE("<b>Exercise 4.3</b> adds adjectives such as <i>throwaway, outgoing, bygone, getaway, off-putting</i>; the Mini dictionary places <i>bygone</i> and <i>getaway</i> in later units. <b>4.5</b>: <i>on/off switch, goings-on, downturn, input, outgoings</i>.",
        "<b>Bài 4.3</b> thêm các tính từ <i>throwaway, outgoing, bygone, getaway, off-putting</i>; Mini dictionary xếp <i>bygone</i> và <i>getaway</i> vào unit sau. <b>4.5</b>: <i>on/off switch, goings-on, downturn, input, outgoings</i>.")
)
def NN(word, d_en, ipa, d_vi, gl, ex_en, ex_vi, form, note, coll, mist, syn, ant, reg="neutral", pos="n."):
    if pos in ("n.", "adj."):
        note += (" Unit 4 lưu ý: học danh từ/tính từ phrasal như một từ riêng – nhớ cả cách viết (liền hay có gạch nối)"
                 " và trọng âm (thường ở động từ nếu động từ đứng trước, ở tiểu từ nếu tiểu từ đứng trước).")
    return PV(word, pos, reg, d_en, ipa, d_vi, gl, ex_en, ex_vi, form, note, coll, mist, syn, ant)
